// starts in; 1 unless set; not dated), and
// the policy version (every change to the rounding mode, the floor, the cap, the terms, the late percent or the
// clerk limit makes a new one, numbered from 1), and
// the role each user name has on the sheet (clerk unless given another), and the delegations of the steward role
// (a steward gives a user the role from a date to a date, inclusive, by the sheet's today).
@Component({
  selector: 'app-settings',
  template: `
    <section aria-label="Settings" data-testid="settings">
      <h2>Settings</h2>
      <p>Policy version: <strong data-testid="policy-version">{{ session.policyVersion() }}</strong></p>
      <form (submit)="save($event)" data-testid="settings-form">
        <label for="setting-clerk-limit">Clerk limit (blank for none)</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          [value]="limit()"
          (input)="limit.set(value($event)); limitTouched.set(true); error.set(null)"
          (focus)="focused.set('limit')"
        />
        <label for="setting-clerk-limit-from">Clerk limit from (YYYY-MM-DD; blank for the sheet's today)</label>
        <input
          id="setting-clerk-limit-from"
          data-testid="setting-clerk-limit-from"
          [value]="fromOf('clerk-limit')"
          (input)="setFrom('clerk-limit', value($event))"
        />
        <p>In force: <strong data-testid="setting-clerk-limit-current">{{ session.clerkLimit() ?? '' }}</strong></p>
        @for (g of grades(); track g) {
          <label [for]="'setting-clerk-limit-' + g">Clerk limit for grade {{ g }} (blank: the sheet's)</label>
          <input
            [id]="'setting-clerk-limit-' + g"
            [attr.data-testid]="'setting-clerk-limit-' + g"
            inputmode="decimal"
            [value]="gradeClerkLimit()[g] ?? ''"
    if (!sid) return 'Enter a sheet id.';
    try {
      const sheet = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(sid)}/load`, null, {
          headers: { 'X-User': user },
        }),
      );
      const descendants = await firstValueFrom(
        this.http.get<DescendantFigures>(`/api/sheets/${encodeURIComponent(sid)}/descendants`, {
          headers: { 'X-User': user },
        }),
      );
      this.sheetId.set(sheet.id);
      this.descendants.set(descendants);
      this.today.set(sheet.today);
      this.settings.set(sheet.settings);
      this.policyVersions.set(sheet.policyVersions ?? []);
      this.policyDate.set(sheet.policyDate);
      this.periodNumberingFrom.set(sheet.periodNumberingFrom);
      this.permissions.set(sheet.permissions);
      this.graceDays.set(sheet.graceDays);
  /** The floor (two decimals) in force on a date: the least a live due of a claim dated then can be. */
  floorOn(date: string): string {
    return this.valueOn('floor', date) ?? STARTING['floor'];
  }

  /** Keep a saved sheet's dated settings and the policy versions their changes made. */
  private keepSettings(sheet: SheetView): void {
    this.settings.set(sheet.settings);
    this.policyVersions.set(sheet.policyVersions ?? []);
  }

  /** The cap (two decimals) in force on a date; null when there is none then. */
  capOn(date: string): string | null {
    return this.valueOn('cap', date);
  }

  /** The policy version in force on a date: the number of versions whose from-date is on or before it (one
   *  with none counts always). */
  policyVersionOn(date: string): number {
    return this.policyVersions().filter((from) => from === null || from <= date).length;
  }

